\u0028\u005a\u006f\u003b\u0050\u0034\u0026\u0026\u006d\u0050\u004d\u002c\u0023\u0022\u003b\u005d\u0036\u0038\u0040\u0035\u0042\u0022\u0036\u0075\u0047\u003b\u0079\u004c\u0071\u004f\u0038\u0029\u007e\u0054\u0026\u0064\u0076\u0062\u004f\u007b\u0045\u002a\u0050\u0026\u0061\u005b\u0077\u0031\u0045\u0076\u0079\u0063\u0071\u005a\u003e\u0053\u0068\u0026\u0046\u002c\u0063\u007c\u0075\u007b\u0051\u0077\u0030\u0036\u0030\u007a\u007b\u0065\u0036\u0075\u0073\u0056\u005b\u006f\u002b\u0059\u0031\u0021\u0021\u0069\u0048\u0034\u0071\u0067\u005a\u0024\u0052\u0060\u0042\u0034\u006e\u0071\u005a\u0024\u0038\u006a\u0059\u0037\u0071\u0050\u0070\u0033\u004f\u0050\u007e\u0066\u0024\u006b\u006c\u0070\u0035\u0021\u0021\u0035\u003f\u006b\u0064\u0041\u007b\u0075\u0079\u004a\u004c\u0050\u003e\u006c\u004b\u005a\u007d\u0029\u0067\u0034\u0030\u0026\u004e\u0021\u0046\u003b\u004b\u005a\u0062\u0051\u0028\u0046\u004c\u0021\u003a\u0066\u002b\u004e\u0046\u0023\u0046\u005f\u0055\u007d\u004d\u006c\u0036\u0055\u007b\u003d\u0055\u0073\u0057\u0063\u004a\u003b\u0063\u0047\u0052\u0067\u0021\u0046\u002a\u0023\u0039\u004e\u0064\u0054\u0071\u0038\u0037\u0066\u007e\u0052\u0028\u0077\u0069\u0045\u007c\u005d\u0051\u007d\u0047\u005d\u002f\u0075\u0061\u006e\u0029\u0056\u007c\u003e\u003d\u0026\u004b\u0069\u0061\u004a\u005b\u002e\u002f\u0061\u0046\u004f\u007e\u002c\u0071\u005a\u006a\u003e\u0025\u005f\u002b\u0078\u0043\u0021\u0047\u007a\u0037\u0053\u007a\u006b\u0029\u0072\u0062\u0021\u0022\u004e\u0057\u0032\u0042\u003a\u0069\u005e\u0048\u0050\u004e\u0077\u0048\u006a\u003f\u006f\u002b\u0077\u0066\u0033\u0034\u0066\u0056\u006a\u006f\u0079\u005a\u007c\u0026\u0032\u0034\u0055\u003e\u0073\u0038\u0043\u002c\u0040\u0047\u0044\u0075\u0029\u005e\u002f\u004c\u004c\u005b\u0040\u0068\u0079\u0059\u006a\u005e\u0061\u0026\u002e\u0048\u0065\u0048\u005d\u0029\u0073\u0074\u007e\u0049\u0037\u0048\u0052\u0068\u0055\u004f\u0051\u0033\u0073\u0061\u007e\u0034\u0053\u0033\u0063\u0042\u005e\u004d\u007b\u005a\u002b\u0073\u005b\u006b\u0042\u0045\u0034\u002a\u006c\u004b\u004b\u0066\u002a\u007b\u003b\u003e\u0022\u0054\u0024\u007a\u0067\u0036\u005d\u003b\u002e\u006d\u002c\u0075\u0033\u0055\u0061\u003e\u007e\u002a\u0060\u0031\u006c\u0050\u0042\u0035\u0026\u004f\u0021\u006e\u0047\u0037\u0071\u0041\u0046\u007e\u007a\u0028\u002c\u0068\u0037\u006f\u0071\u0035\u006b\u0028\u005a\u002f\u0029\u0071\u0041\u0025\u0071\u0070\u004c\u0045\u0063\u006d\u0075\u0054\u004a\u0057\u0039\u0053\u0048\u003e\u0072\u003b\u0050\u005a\u0069\u0078\u005a\u0070\u0022\u0022\u0023\u0025\u0033\u0056\u0057\u005d\u0029\u0055\u002e\u006b\u0046\u0041\u0036\u004d\u005f\u0054\u0054\u0077\u0029\u005d\u003a\u005a\u002a\u0057\u0078\u0079\u006c\u0024\u0068\u005f\u0053\u002e\u0071\u0070\u004d\u006c\u006b\u005a\u006a\u0041\u005b\u0033\u0037\u0061\u004c\u0042\u004c\u0025\u006a\u0075\u002f\u005f\u007c\u0051\u006c\u007d\u0042\u0022\u005e\u0075\u006b\u007c\u0063\u006d\u007c\u0070\u0040\u0021\u0058\u0049\u0070\u0064\u002a\u005a\u0053\u0042\u005b\u0036\u004c\u0023\u0032\u0071\u005d\u0045\u0047\u006c\u0033\u0050\u0067\u006e\u007b\u0040\u0057\u0023\u0074\u003a\u0055\u004c\u0030\u0067\u0071\u0064\u003c\u005d\u0028\u006c\u007e\u003b\u0066\u003a\u0036\u0051\u0055\u0075\u007c\u0038\u0038\u0067\u0026\u0076\u0025\u004e\u0076\u0065\u0070\u0030\u006d\u0062\u0047\u005e\u003e\u0064\u004f\u0032\u002a\u0065\u0023\u007b\u004d\u0050\u0072\u004d\u006d\u0023\u004e\u0040\u003b\u0037\u0031\u003c\u0065\u002f\u005f\u0056\u0061\u0023\u005d\u006e\u007d\u0030\u0078\u004e\u002f\u0052\u005d\u0036\u0048\u006f\u0037\u0050\u0040\u0047\u003a\u0055\u003b\u0052\u005d\u0036\u0048\u0060\u0025\u0058\u0032\u005d\u0073\u0058\u0069\u0067\u007c\u0055\u0050\u005a\u0057\u005f\u007b\u003e\u0051\u004f\u0051\u0034\u0046\u005b\u0026\u0021\u0047\u0026\u0026\u0064\u007a\u007d\u0045\u006c\u003c\u005a\u003e\u002b\u006b\u0070\u007b\u003e\u002a\u0071\u0041\u0040\u0044\u0068\u002c\u0050\u0062\u0029\u0066\u0077\u004c\u0026\u0072\u0057\u0069\u0062\u005b\u0052\u0060\u007c\u007a\u0029\u0066\u0037\u0029\u0075\u007d\u0024\u0032\u0029\u005b\u0076\u005e\u004d\u003c\u004f\u0046\u004e\u007a\u005b\u002e\u005e\u004d\u0033\u0034\u0032\u003a\u0040\u007a\u0043\u0043\u002a\u0071\u006a\u006f\u0044\u0023\u0070\u002f\u0045\u0061\u004a\u002b\u002b\u007b\u0044\u0041\u006a\u0075\u0064\u0066\u005e\u006d\u0047\u0038\u0044\u0051\u0040\u0051\u0070\u0030\u0022\u0033\u007c\u006b\u0043\u004c\u0025\u0067\u0061\u005d\u0061\u005d\u0022\u0071\u0060\u0033\u003c\u005d\u004d\u005d\u0033\u0042\u0034\u0035\u0054\u005e\u0067\u0044\u0057\u0073\u006a\u002e\u006e\u0055\u0032\u0025\u006e\u002f\u0071\u002e\u0079\u0053\u0032\u0055\u003f\u0051\u0034\u003e\u004c\u0057\u006c\u0065\u0031\u0075\u0029\u0070\u0069\u002e\u006c\u006c\u0037\u0077\u002e\u0039\u004f\u005a\u0069\u0044\u005e\u0078\u0024\u0078\u0072\u007d\u0047\u0036\u0069\u003a\u0077\u005f\u0023\u0068\u0068\u004d\u005e\u0047\u0069\u005b\u0071\u0046\u0043\u0067\u003d\u0039\u0039\u005d\u0064\u0035\u0054\u0053\u0023\u007d\u002e\u0024\u0029\u006f\u0071\u0074\u002f\u0066\u006b\u0040\u0073\u0029\u005b\u003b\u0067\u0040\u003a\u0074\u004f\u007e\u0053\u0055\u005f\u0037\u0040\u0040\u004c\u005b\u0071\u0074\u005f\u0073\u0034\u0032\u0037\u0025\u003e\u0023\u005d\u0057\u002a\u0040\u0066\u0041\u0025\u002b\u0025\u005f\u0059\u006d\u0043\u0058\u0078\u0048\u0078\u007c\u0053\u0041\u0021\u002b\u007c\u005d\u0073\u007d\u0074\u0044\u004d\u003b\u005e\u003f\u0032\u005a\u0024\u002a\u0078\u003d\u007c\u0065\u0040\u0056\u005e\u006c\u0069\u0037\u0048\u007e\u0030\u0033\u003b\u0058\u0036\u003d\u0057\u0079\u006e\u007d\u0040\u004a\u007a\u0079\u0063\u0035\u002b\u0078\u0065\u0053\u007e\u003d\u007a\u0054\u005d\u0078\u0026\u004a\u0039\u0068\u0077\u0049\u0050\u003b\u0021\u0025\u0064\u0035\u0079\u006f\u0044\u0079\u0062\u0074\u0023\u0054\u0074\u0070\u0029\u0062\u0050\u0068\u0057\u0077\u0076\u003e\u0065\u0031\u007a\u0054\u006a\u0047\u0066\u0061\u0053\u006b\u0072\u003b\u0023\u0023\u005d\u0026\u0053\u004c\u003d\u0041\u004b\u0026\u0065\u0041\u0070\u0079\u002a\u0072\u002a\u0034\u0070\u007a\u0023\u0070\u002c\u002a\u0029\u0076\u003b\u0061\u0054\u006f\u0069\u0036\u0045\u0072\u0075\u0059\u0034\u007a\u0073\u0061\u007d\u0028\u0069\u003d\u0069\u0022\u0057\u005e\u0065\u0070\u0021\u006b\u005f\u002c\u006f\u0028\u004c\u0075\u0047\u0026\u0050\u0073\u0059\u007d\u0021\u003b\u0045\u003d\u0041\u002c\u0057\u005e\u0065\u007d\u0069\u0032\u004b\u0037\u0049\u0079\u0038\u004d\u0073\u0053\u006c\u0037\u0078\u004d\u0045\u0062\u0041\u006b\u0053\u004d\u0073\u003a\u0046\u0043\u006f\u0031\u0039\u004d\u006d\u0075\u007b\u0058\u0056\u0029\u0073\u0043\u005b\u0051\u0054\u0035\u0074\u0065\u0037\u002a\u003d\u0050\u0031\u0039\u004d\u006d\u0075\u007b\u0063\u005b\u0048\u0038\u0028\u006b\u0076\u004c\u0064\u0046\u006f\u0071\u0048\u004f\u005e\u007c\u0049\u0028\u0054\u0043\u0069\u0064\u0044\u004a\u0036\u007c\u0071\u0031\u0061\u002e\u0039\u0042\u0021\u003b\u0045\u0031\u0053\u0054\u0032\u0061\u002e\u0028\u0064\u007a\u002b\u0026\u0060\u005b\u0043\u0035\u002c\u003d\u0041\u0029\u0072\u006a\u0021\u0046\u0076\u0060\u0024\u0063\u0047\u007a\u006d\u0059\u0058\u006c\u0060\u0047\u0039\u0038\u0044\u004b\u0021\u0036\u0078\u0034\u004c\u005a\u004c\u0060\u0041\u0048\u0052\u0046\u002a\u0045\u002f\u003a\u005f\u0078\u0056\u0039\u003e\u0022\u0043\u0034\u005e\u0055\u0042\u0024\u004d\u0034\u003c\u006d\u0035\u003b\u0065\u0077\u0079\u0037\u005a\u0075\u0058\u0055\u0023\u005e\u0077\u0042\u004c\u0076\u005f\u0045\u005a\u0034\u0076\u0046\u005d\u0062\u005e\u0023\u002f\u006c\u0028\u004c\u007a\u0071\u0078\u0026\u005f\u006b\u0077\u0029\u0032\u006c\u007d\u0046\u0067\u0046\u0077\u005e\u005b\u0034\u0032\u006c\u0053\u0071\u0061\u0076\u0044\u0022\u0073\u0078\u0055\u006f\u002e\u0065\u0075\u0071\u0067\u0032\u006d\u007d\u007b\u007b\u0052\u004b\u003f\u0057\u0076\u003d\u0031\u004e\u0032\u007b\u007c\u007a\u0051\u0070\u0037\u0030\u0031\u003d\u0028\u005d\u004c\u004c\u0073\u007d\u0044\u0045\u004c\u0059\u0022\u0062\u0047\u0060\u0042\u005f\u0025\u0052\u0036\u0060\u0071\u0067\u0071\u006b\u0060\u0037\u003f\u0037\u005e\u005f\u0034\u0025\u0070\u007c\u0056\u0072\u0071\u005b\u0025\u0061\u007c\u0028\u0028\u003c\u0069\u0053\u0026\u0021\u0053\u006e\u0038\u0025\u0053\u0052\u0038\u0041\u0065\u0076\u0054\u002e\u0046\u0079\u006c\u0065\u0036\u006e\u003f\u003e\u0071\u0076\u0075\u0051\u0065\u006e\u0036\u006e\u002a\u0055\u002e\u003b\u0056\u003d\u006e\u007a\u0064\u0060\u0054\u0043\u0067\u0063\u0078\u002a\u003e\u0074\u0047\u0038\u002a\u0059\u0058\u005d\u002b\u0043\u0032\u004c\u0054\u0039\u006b\u004b\u006a\u0047\u004c\u0069\u006a\u0048\u0055\u002b\u006f\u0066\u005d\u002c\u002c\u0032\u004c\u0054\u0039\u0077\u0041\u0068\u003f\u005d\u004d\u0059\u006a\u006a\u003d\u0030\u0068\u0038\u0025\u0053\u0052\u0038\u0041\u007c\u0070\u0036\u0057\u005b\u0066\u0046\u0051\u0048\u0071\u0072\u0071\u003d\u006e\u0074\u0023\u0053\u0071\u0036\u0038\u0025\u005a\u0041\u0079\u007d\u007d\u0054\u0028\u0025\u0028\u0021\u0055\u006c\u006e\u0079\u004c\u0040\u004c\u0053\u0075\u0029\u0073\u0040\u006e\u006c\u0065\u0036\u006e\u0079\u0064\u003a\u0076\u004b\u004a\u003f\u0046\u0071\u0053\u0052\u002b\u0077\u002a\u0055\u0058\u0023\u007e\u006b\u0063\u0072\u0071\u005b\u0025\u0061\u007c\u006b\u0076\u0073\u0034\u0061\u0063\u0069\u0057\u0061\u0079\u0063\u0041\u0036\u006e\u0071\u0076\u006b\u0054\u0040\u0077\u0022\u0024\u007c\u003b\u0064\u0051\u005f\u0055\u0060\u002a\u0040\u0037\u0023\u0078\u0034\u003e\u002a\u0061\u005a\u0063\u0072\u0072\u0021\u0075\u0038\u0025\u0053\u0052\u0038\u0041\u007c\u0070\u0036\u0057\u005b\u0066\u0046\u0051\u0069\u0071\u0040\u0078\u0051\u005f\u0039\u007d\u0078\u0026\u0038\u0025\u0048\u0061\u006a\u004f\u007e\u0054\u0076\u0050\u004b\u006f\u0033\u0030\u0031\u0026\u0076\u0037\u004a\u0055\u002b\u0069\u0039\u0078\u0025\u0045\u0048\u0040\u0056\u006d\u0033\u0067\u0028\u003e\u0038\u0036\u003d\u0060\u0073\u0041\u0028\u0076\u0035\u003e\u004c\u0021\u007a\u007d\u0072\u0056\u007c\u003d\u0074\u0041\u006d\u0024\u006a\u0040\u0048\u0039\u002c\u0051\u0023\u005f\u0067\u0042\u0047\u0033\u002f\u005f\u003e\u007d\u0032\u006a\u006d\u0071\u0028\u0063\u0037\u0024\u0039\u007c\u0026\u004f\u0036\u0057\u0063\u0031\u0036\u0054\u0055\u0022\u0079\u0052\u0076\u0065\u0026\u0024\u004c\u0054\u0030\u0040\u006d\u0073\u003a\u0052\u0034\u0053\u003a\u0034\u006d\u0069\u003e\u0053\u003f\u002b\u006e\u006f\u0029\u0053\u0062\u003e\u002a\u0064\u005b\u003d\u0063\u0048\u0046\u003a\u0036\u0044\u0076\u0036\u0069\u0054\u0062\u0073\u0040\u0071\u0057\u0076\u003a\u0070\u0022\u0056\u003d\u0074\u0076\u0054\u0072\u0053\u003d\u003a\u006c\u0054\u0062\u0073\u0040\u0071\u0057\u0026\u002e\u0038\u0063\u0022\u005d\u0069\u006b\u003d\u004a\u0031\u0077\u006b\u006c\u0078\u0054\u003b\u0037\u0025\u0063\u0023\u0038\u002b\u0075\u006c\u0046\u0071\u006d\u004e\u0072\u0070\u004d\u007c\u0062\u0069\u0057\u004e\u0042\u0065\u0054\u006d\u007d\u003e\u0031\u006c\u0058\u002c\u0040\u0023\u0036\u0078\u002a\u004f\u0035\u0035\u003c\u0040\u007d\u007b\u002b\u0035\u0023\u0042\u006a\u007e\u0071\u007d\u003e\u0031\u006c\u0058\u002c\u0074\u0021\u0039\u0030\u0046\u0073\u0044\u0054\u0035\u0064\u0070\u0056\u0054\u0048\u0072\u0071\u0028\u0071\u0024\u004b\u005f\u0030\u003b\u0072\u0078\u0076\u003a\u006d\u0042\u002b\u0031\u003b\u0066\u0045\u0028\u005f\u0074\u006a\u002f\u0065\u0032\u0035\u0039\u007a\u003e\u007e\u0044\u006d\u0054\u007d\u0024\u007c\u006d\u005d\u0066\u0067\u0058\u004c\u0056\u006c\u0060\u0029\u0022\u0039\u0068\u006d\u0072\u0029\u0067\u004b\u0028\u006d\u0022\u0025\u0050\u0040\u003e\u004d\u004e\u0067\u0058\u004c\u0056\u006c\u0060\u0070\u0077\u003c\u0054\u0021\u004d\u0066\u0039\u006d\u0061\u006f\u006b\u0039\u003f\u003e\u003c\u006a\u0024\u004b\u005f\u0030\u003b\u0072\u0035\u004e\u0054\u0071\u0069\u0079\u003d\u003c\u0072\u004f\u0035\u003a\u006d\u006c\u004b\u0034\u0053\u0075\u0075\u007a\u007e\u0035\u0073\u006a\u0041\u0026\u0063\u0052\u0074\u0078\u0022\u0041\u006d\u0078\u002e\u0042\u0066\u002c\u0063\u002f\u006d\u0051\u0073\u0048\u0052\u0039\u0064\u004b\u0051\u0062\u0064\u0029\u0028\u0036\u0035\u0070\u0032\u0047\u0058\u0042\u006d\u0051\u0073\u0048\u0023\u0063\u0045\u0069\u0056\u0056\u004d\u0062\u003a\u004d\u0037\u0032\u0057\u0025